begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.ma(t text) returns uuid language sql immutable as $$select md5('agenda-saved-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.ma(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.ma(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-saved@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed']) t;
insert into public.organizations(id,name,slug,status) values(pg_temp.ma('org'),'Agenda fictícia','agenda-saved-test','active'),(pg_temp.ma('other'),'Outro ministério','agenda-saved-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.ma('unit'),pg_temp.ma('org'),'Igreja fictícia A','a','headquarters'),(pg_temp.ma('unitb'),pg_temp.ma('org'),'Igreja fictícia B','b','campus'),(pg_temp.ma('unitc'),pg_temp.ma('other'),'Igreja externa','c','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.ma(t||'-m'),pg_temp.ma('org'),pg_temp.ma(t),pg_temp.ma('unit'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status) select pg_temp.ma(t||'-p'),pg_temp.ma('org'),pg_temp.ma('unit'),pg_temp.ma(t),t||' fictício','active' from unnest(array['member','second'])t;
insert into private.church_app_events(id,organization_id,unit_id,title,kind,starts_at,ends_at,capacity) values(pg_temp.ma('event'),pg_temp.ma('org'),pg_temp.ma('unit'),'Encontro fictício','event',now()+interval '1 hour',now()+interval '3 hours',1),(pg_temp.ma('draftb'),pg_temp.ma('org'),pg_temp.ma('unitb'),'Rascunho secreto','service',now()+interval '2 days',now()+interval '3 days',10);
create function pg_temp.admin(a text,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_agenda_admin(pg_temp.ma('org'),pg_temp.ma('unit'),a,pg_temp.ma('event'),v,d)$$;
-- Agenda do app · categoria do evento e eventos salvos.
insert into private.programming_categories(id,organization_id,unit_id,name,color) values(pg_temp.ma('cat'),pg_temp.ma('org'),pg_temp.ma('unit'),'Jovens','#d81b60');
select pg_temp.actor('owner');set local role authenticated;
select lives_ok($$select pg_temp.admin('publish',1)$$,'evento publicado');
reset role;
update private.church_app_events set category_id=pg_temp.ma('cat') where id=pg_temp.ma('event');
set local role authenticated;
reset role;set local role anon;
select is(public.member_agenda(pg_temp.ma('org'),pg_temp.ma('unit'))->'items'->0->>'category','Jovens','app recebe a categoria');
select is(public.member_agenda(pg_temp.ma('org'),pg_temp.ma('unit'))->'items'->0->>'category_color','#d81b60','e a cor da categoria');
select ok(not has_function_privilege('anon','public.member_saved_events(uuid,text,uuid)','execute'),'visitante não salva');
reset role;
select pg_temp.actor('member');set local role authenticated;
select is(jsonb_array_length(public.member_saved_events(pg_temp.ma('org'))->'items'),0,'começa sem salvos');
select is(public.member_saved_events(pg_temp.ma('org'),'save',pg_temp.ma('event'))->'items'->>0,pg_temp.ma('event')::text,'salva evento');
select is(jsonb_array_length(public.member_saved_events(pg_temp.ma('org'),'save',pg_temp.ma('event'))->'items'),1,'salvar de novo não duplica');
select throws_ok($$select public.member_saved_events(pg_temp.ma('org'),'save',pg_temp.ma('draftb'))$$,'22023',null,'rascunho não pode ser salvo');
reset role;select pg_temp.actor('second');set local role authenticated;
select is(jsonb_array_length(public.member_saved_events(pg_temp.ma('org'))->'items'),0,'cada conta vê só os próprios salvos');
reset role;select pg_temp.actor('member');set local role authenticated;
select is(jsonb_array_length(public.member_saved_events(pg_temp.ma('org'),'remove',pg_temp.ma('event'))->'items'),0,'remove dos salvos');
select throws_ok($$select public.member_saved_events(pg_temp.ma('org'),'apagar',null)$$,'22023',null,'ação inválida recusada');
select * from finish();
rollback;
